FIXED_TIME=(1980,1,1,0,0,0)
def generate(output_dir:pathlib.Path)->None:
 output_dir.mkdir(parents=True,exist_ok=True)
 for package,entries in PACKAGES.items():
  with zipfile.ZipFile(output_dir/package,"w",compression=zipfile.ZIP_DEFLATED) as archive:
   for name,text in entries.items():
    info=zipfile.ZipInfo(name,FIXED_TIME);info.create_system=3;info.external_attr=0o644<<16;info.compress_type=zipfile.ZIP_DEFLATED
    archive.writestr(info,text.encode("utf-8"))
def main()->None:
 parser=argparse.ArgumentParser();parser.add_argument("output_dir",type=pathlib.Path);generate(parser.parse_args().output_dir)
if __name__=="__main__":main()
